def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    # Build sequences
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]

    opp_coops = op.count('C')
    opp_defects = n - opp_coops
    rate = opp_coops / n

    # Opponent's current cooperation streak
    op_coop_streak = 0
    for a in reversed(op):
        if a == 'C':
            op_coop_streak += 1
        else:
            break

    # Opponent's current defect streak
    op_def_streak = 0
    for a in reversed(op):
        if a == 'D':
            op_def_streak += 1
        else:
            break

    # If opponent has been extremely cooperative and never defects,
    # exploit near the end, but cooperate up to then to keep them cooperative.
    if opp_defects == 0:
        if n >= 97:
            return 'D'
        if n >= 90 and n % 3 == 0:
            return 'D'
        return 'C'

    # If opponent is overwhelmingly cooperative, cooperate
    if rate >= 0.85:
        if last_op == 'D':
            # Forgive isolated defection in an otherwise cooperative partner
            if op_def_streak >= 3:
                return 'D'
            return 'C'
        return 'C'

    # If opponent is overwhelmingly defective, defect but probe occasionally
    if rate <= 0.2:
        if op_def_streak >= 1 and n < 95:
            return 'D'
        if n >= 95:
            return 'D'
        if n % 15 == 0:
            return 'C'
        return 'D'

    # Long defection streak: punish
    if op_def_streak >= 3:
        return 'D'

    # Use recent window to gauge direction
    window = min(12, n)
    recent = op[-window:]
    recent_coop = recent.count('C')
    recent_rate = recent_coop / window

    # Late game: if opponent below half, defect; if high, cooperate
    if n >= 85:
        if rate < 0.5 or recent_rate < 0.4:
            return 'D'
        return 'C'

    # If opponent just defected after cooperating for a while,
    # punish once, but don't get stuck in retaliation.
    if last_op == 'D':
        # If short isolated defection and historically cooperative, forgive
        if op_def_streak == 1 and rate > 0.6:
            return 'C'
        # If our last was D and opponent defected, continue punishment one round
        if last_my == 'D':
            # If they have mostly cooperated, switch to reconcile
            if recent_rate >= 0.5:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last.
    if last_my == 'D':
        # we defected and they still cooperated: don't exploit indefinitely
        return 'C'

    # If recent trend shifted toward defection, be wary
    if window >= 6 and recent_rate + 0.3 < rate and recent_coop <= window - 3:
        return 'D'

    # If recent cooperation is strong, cooperate
    if recent_rate >= 0.7:
        return 'C'

    # Mid-range: tit-for-tat with mild forgiveness and rare probe
    if last_op == 'C':
        # occasional probe against a partner that has shown mild defection
        if rate < 0.7 and op_coop_streak >= 5 and rng.random() < 0.06:
            return 'D'
        return 'C'

    return 'C'
